// Optional isolated PostgreSQL QA: node tests/fixtures/sample-campaign-db-check.mjs /absolute/path/to/pglite/dist/index.js
const { PGlite } = await import(process.argv[2] || '@electric-sql/pglite');
import { readFile } from 'node:fs/promises';
import assert from 'node:assert/strict';
import { fileURLToPath } from 'node:url';
const root=fileURLToPath(new URL('../../', import.meta.url)).replace(/\/$/, '');
const {campaignMonth}=await import(`${root}/lib/sample-campaign.mjs`);
const month=campaignMonth();
const db=new PGlite();
await db.exec('create role anon; create role authenticated; create role service_role bypassrls;');
await db.exec(await readFile(`${root}/supabase/sample-campaign-preview.sql`,'utf8'));
const settings={title:'QA campaign',rules:'QA initial rules',codes:['NV-001','NV-002'],selectionCount:1,capacity:2};
const save=async(revision,enabled,values=settings)=> (await db.query('select save_nova_sample_campaign($1,$2,$3,$4::jsonb,$5) as value',[month,revision,enabled,JSON.stringify(values),'owner@example.test'])).rows[0].value;
const apply=async(id,phone,key='request_'+phone,revision=1,codes=['NV-001'])=> (await db.query('select create_nova_sample_application($1::uuid,$2,$3,$4,$5,$6,$7::text[],$8) as value',[id,month,revision,'QA applicant',phone,'QA address',codes,key])).rows[0].value;
const id1='11111111-1111-4111-8111-111111111111',id2='22222222-2222-4222-8222-222222222222',id3='33333333-3333-4333-8333-333333333333';
assert.equal((await save(0,true)).revision,1);
assert.equal((await apply(id1,'09123456789')).status,'pending');
assert.equal((await apply(id1,'09123456789')).duplicate,true);
await assert.rejects(apply(id2,'09123456789','different_request'),/ALREADY_APPLIED/);
await assert.rejects(apply(id2,'09234567890','request_2',1,['NV-003']),/INVALID_SELECTION/);
await assert.rejects(apply(id2,'09234567890','request_2',0),/CAMPAIGN_CHANGED/);
await save(1,true,{...settings,rules:'QA revised rules'});
const old=(await db.query('select campaign_snapshot,campaign_revision from nova_sample_applications where id=$1',[id1])).rows[0];
assert.equal(old.campaign_snapshot.rules,'QA initial rules');assert.equal(old.campaign_revision,1);
await assert.rejects(save(1,false),/CAMPAIGN_CHANGED/);
await apply(id2,'09234567890','request_2',2);
await assert.rejects(apply(id3,'09345678901','request_3',2),/CAMPAIGN_FULL/);
await save(2,false);
await assert.rejects(apply(id3,'09345678901','request_3',3),/CAMPAIGN_CLOSED/);
assert.equal((await apply(id1,'09123456789')).duplicate,true);
await assert.rejects(apply(id3,'09345678901','request_09123456789',1),/REQUEST_CONFLICT/);
await db.query('select update_nova_sample_status($1::uuid,$2,$3)',[id1,'approved','owner@example.test']);
assert.equal((await db.query('select status from nova_sample_applications where id=$1',[id1])).rows[0].status,'approved');
await db.exec('set role anon;');
await assert.rejects(db.query('select * from nova_sample_applications'),/permission denied/);
await assert.rejects(db.query('select * from nova_sample_campaigns'),/permission denied/);
await assert.rejects(db.query('select update_nova_sample_status($1::uuid,$2,$3)',[id1,'shipped','attacker']),/permission denied/);
await db.exec('reset role;');
await db.close();
console.log('PASS: schema/RPC execution, idempotency, duplicate phone, allowed codes, revision locks, immutable rules, quota, close/retry, status update, and anonymous table/RPC denial.');
